    {"claim": "The accountability gap in AI tort cases is not a defect in our legal doctrine — it is a defect in who controls the evidence.", "targets": [], "relationship": ""},
    {"claim": "The FAA delegated 737 MAX certification to Boeing, and 346 people died across two crashes in 2018 and 2019 when the party that built the aircraft also controlled the record of its airworthiness.", "targets": [], "relationship": ""},
    {"claim": "A tamper-evident log lets a court distinguish a genuine defect from bad luck — without it, that distinction is unprovable, and strict liability becomes a slogan rather than an enforceable rule.", "targets": [], "relationship": ""},
    {"claim": "The cost of disclosure in a domain where you alone hold the evidence of your own potential negligence is not over-deterrence — it is the proper internalization of a risk you created.", "targets": [], "relationship": ""},
    {"claim": "Completeness guarantees must be technically verifiable, and the keying scheme must not itself become a metric the defendant games.", "targets": [], "relationship": ""}
  ]
}

